pub fn splitlines(a: Vec<String>, keepends: bool) -> Vec<Vec<String>> {
    a.into_iter()
        .map(|s| {
            // Produce a non-empty Vec<String> for each input string.
            // We split on '\n'. If the string is empty or has only delimiters,
            // we still ensure at least one element.
            let mut parts: Vec<String> = Vec::new();
            let mut start: usize = 0;
            let bytes = s.as_bytes();

            for (i, &b) in bytes.iter().enumerate() {
                if b == b'\n' {
                    // segment: s[start..i] (without '\n') or s[start..=i] (with '\n')
                    let end = if keepends { i + 1 } else { i };
                    parts.push(s[start..end].to_string());
                    start = i + 1;
                }
            }

            // trailing segment (after last '\n')
            if start <= s.len() {
                parts.push(s[start..].to_string());
            }

            // Guarantee non-empty inner list even for pathological cases (shouldn't happen here).
            if parts.is_empty() {
                parts.push(String::new());
            }

            parts
        })
        .collect()
}